    elif obj is not None:
        text = str(obj)          # 合法但非对象的 JSON：当文本处理，别崩
    else:
        # 非 JSON 载荷 = 设备上传的 16k 单声道 PCM
        print("[ASR] 收到语音 %d 字节，开始识别 ..." % len(payload))
        # 先给设备一个即时回执：否则识别期间设备会一直显示"等待"，久一点就报超时
