    """每个请求独立线程处理：
    之前用单线程队列，语音请求要跑 5~8 秒(ASR+LLM+TTS)，
    连点几次后面的就会排队超过设备 20 秒的等待上限 -> 屏幕显示"云端无响应"。"""
    try:
        if topic == TOPIC_REQ:
            handle_request(payload)
        elif topic == TOPIC_ALERT:
            handle_alert(payload)
    except Exception as e:
        print("[worker] 处理异常:", type(e).__name__, e)


