        c.subscribe(t, qos=1)
        print("  订阅:", t)


def on_message(c, u, msg):
    print("[收到]", msg.topic, "len=%d" % len(msg.payload))
    if msg.topic in (TOPIC_REQ, TOPIC_ALERT):
        threading.Thread(target=worker, args=(msg.topic, msg.payload),
                         daemon=True).start()

